From c9fd0ee7023f37a6648ce75b3413339b8b68ecbd Mon Sep 17 00:00:00 2001
From: Sebastian Heimann <sebastian.heimann@gfz-potsdam.de>
Date: Mon, 1 Apr 2019 12:23:53 +0200
Subject: [PATCH] gf: fix low-level errors in time handling

Fixes an error introduced in ff78d61d9bea8d70389d64507f7f1ae40ba66b3a
which could lead to incorrect time information on synthetic seismograms
produced by LocalEngine.process.

diff --git a/src/gf/store.py b/src/gf/store.py
index 2a2c706b..aa3c9c21 100644
--- a/src/gf/store.py
+++ b/src/gf/store.py
@@ -1832,11 +1832,13 @@ definitions: %s.\n Travel time table contains holes in probed ranges.''' % w
         else:
             delays = source.times*0
             itsnapshot = 1
+
         scheme_desc = meta.component_scheme_to_description[
             self.config.component_scheme]

         if ntargets == 0:
             raise StoreError('MultiLocation.coords5 is empty')
+
         res = store_ext.store_calc_static(
             self.cstore,
             source.coords5(),
@@ -1902,8 +1904,8 @@ definitions: %s.\n Travel time table contains holes in probed ranges.''' % w

         if itmin is None:
             itmin = num.zeros(nreceiver, dtype=num.int32)
-
-        itmin = (itmin-itoffset).astype(num.int32)
+        else:
+            itmin = (itmin-itoffset).astype(num.int32)

         if nsamples is None:
             nsamples = num.zeros(nreceiver, dtype=num.int32) - 1
@@ -1989,7 +1991,7 @@ definitions: %s.\n Travel time table contains holes in probed ranges.''' % w
                 scheme,
                 interpolation, nthreads)

-        except store_ext.StoreExtError as e:
+        except store_ext.StoreExtError:
             raise meta.OutOfBounds()

         provided_components = scheme_desc.provided_components

diff --git a/src/gf/ext/store_ext.c b/src/gf/ext/store_ext.c
index 45166ed5..66d551e1 100644
--- a/src/gf/ext/store_ext.c
+++ b/src/gf/ext/store_ext.c
@@ -166,12 +166,6 @@ typedef struct {

 #define VICINITY_NIP_MAX 8

-typedef enum {
-    TYPE_A = 0,
-    TYPE_B,
-    TYPE_C,
-} mapping_scheme_id;
