     {"elastic5", 3, 3, 3, nsummands_elastic5, igs_elastic5, make_weights_elastic5},
     {"elastic8", 6, 3, 5, nsummands_elastic8, igs_elastic8, make_weights_elastic8},
@@ -603,7 +611,6 @@ static store_error_t store_sum(
     float64_t delay;
     trace_t trace;
