-        }
-
-        result->buf_pos = result->buf_pos - ishift;
-        result->data = result->buffer + result->buf_pos;
-        result->itmin = itmin;
+        result->data -= ishift;
+        result->nsamples += ishift;
+        result->itmin -= ishift;
     }

